// @file ./experiments/db-qa-baseline.ts
import { defineExperiment } from "niceeval";
import { dbGptV2Agent } from "../agents/dbgpt-v2.ts";

export default defineExperiment({
  description: "DB-GPT database-QA baseline against the local safe fixture",
  agent: dbGptV2Agent({
    baseUrl: "http://127.0.0.1:5670",
    database: "niceeval_fixture",
  }),
  // DB-GPT's shipped reference configuration uses this model name. The local
  // controller must be started and queried before treating it as verified.
  model: "gpt-4o",
  attempts: 1,
  maxConcurrency: 1,
  timeoutMs: 120_000,
});
// @file ./niceeval.config.ts
import { defineConfig } from "niceeval";

export default defineConfig({
  // Add experiments/ with defineExperiment(...) to run evals.
  //
  // IMPORTANT(judge): semantic assertions (t.judge.*) are unavailable until a judge
  // model is configured. A required unavailable assertion errors the attempt; only
  // .optional() leaves its Verdict unchanged. Any OpenAI-compatible /chat/completions
  // service works; the key is read from NICEEVAL_JUDGE_KEY unless apiKeyEnv says otherwise.
  // judge: { model: "gpt-5.4-mini" },
});

// @file ./agents/dbgpt-v2.ts
import { defineDirectAgent, type Agent, type EvidenceCoverage } from "niceeval/adapter";

const evidenceCoverage = {
  events: {
    status: "partial",
    reason: "DB-GPT V2 emits answer deltas but not a complete event history.",
  },
  actions: {
    status: "unavailable",
    reason: "DB-GPT V2 does not expose database or tool lifecycle events in this stream.",
  },
  messages: { status: "complete" },
  usage: {
    status: "partial",
    reason: "Usage is included only when the upstream stream supplies it.",
  },
  status: { status: "complete" },
  data: {
    status: "unavailable",
    reason: "The selected endpoint returns prose rather than a structured business result.",
  },
} satisfies EvidenceCoverage;

type DbGptAgentOptions = {
  baseUrl: string;
  database: string;
};

type ChatChunk = {
  choices?: Array<{ delta?: { content?: string }; message?: { content?: string } }>;
  usage?: { prompt_tokens?: number; completion_tokens?: number };
  error?: { message?: string };
};

export function dbGptV2Agent(options: DbGptAgentOptions): Agent {
  return defineDirectAgent({
    name: "dbgpt-v2-db-qa",
    evidenceCoverage,
    async send(input, ctx) {
      ctx.progress({ message: "Waiting for DB-GPT database QA" });
      const response = await fetch(`${options.baseUrl}/api/v2/chat/completions`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          model: ctx.model,
          messages: [{ role: "user", content: input.text }],
          stream: true,
          incremental: true,
          conv_uid: ctx.session.id,
          chat_mode: "chat_with_db_qa",
          chat_param: options.database,
        }),
        signal: ctx.signal,
      });

      if (!response.ok || !response.body) {
        throw new Error(`DB-GPT V2 request failed with HTTP ${response.status}`);
      }

      let reply = "";
      let failure: string | undefined;
      let usage: ChatChunk["usage"];
      const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
      let buffer = "";

      const consume = (block: string) => {
        for (const line of block.split("\n")) {
          if (!line.startsWith("data:")) continue;
          const data = line.slice(5).trim();
          if (!data || data === "[DONE]") continue;
          try {
            const chunk = JSON.parse(data) as ChatChunk;
            reply += chunk.choices?.[0]?.delta?.content ?? chunk.choices?.[0]?.message?.content ?? "";
            usage = chunk.usage ?? usage;
            failure ??= chunk.error?.message;
          } catch {
            failure ??= "DB-GPT returned a non-JSON SSE data frame.";
          }
        }
      };

      for (;;) {
        const { done, value } = await reader.read();
        buffer += value ?? "";
        let separator: number;
        while ((separator = buffer.indexOf("\n\n")) !== -1) {
          consume(buffer.slice(0, separator));
          buffer = buffer.slice(separator + 2);
        }
        if (done) break;
      }
      if (buffer.trim()) consume(buffer);

      if (failure) {
        return { status: "failed", events: [{ type: "error", message: failure }] };
      }
      if (!reply.trim()) {
        return {
          status: "failed",
          events: [{ type: "error", message: "DB-GPT completed without an assistant response." }],
        };
      }

      return {
        status: "completed",
        events: [{ type: "message", role: "assistant", text: reply }],
        usage: usage
          ? { inputTokens: usage.prompt_tokens, outputTokens: usage.completion_tokens }
          : undefined,
      };
    },
  });
}

// @file ./evals/db-qa/orders.eval.ts
import { defineEval } from "niceeval";
import { includes } from "niceeval/expect";

export default [
  defineEval({
    description: "Reports the completed-order total from the fixture database",
    async test(t) {
      await t.send("What is the total paid amount for completed orders?");
      t.succeeded();
      t.check(t.reply, includes(/(?:\$\s*)?175(?:\.0{1,2})?\b/));
    },
  }),
  defineEval({
    description: "Refuses to invent a result for a product absent from the fixture",
    async test(t) {
      await t.send("How many completed orders contain product Zebra-99?");
      t.succeeded();
      t.check(t.reply, includes(/(?:not found|no (?:matching )?(?:records?|orders?)|does not exist|unable to find)/i));
    },
  }),
];

